function downloadSize(bytes){return !bytes?'ZIP':bytes>=1024*1024?fmt(bytes/1024/1024,1)+' MB':fmt(bytes/1024,1)+' KB';}
function downloadFileName(file){return file.path.split('/').at(-1);}
function downloadHref(file){return file.url.includes('supabase.co/')?file.url+'?download='+encodeURIComponent(downloadFileName(file)):file.url;}
function downloadLink(file,classes='download-file'){return '<a class="'+classes+'" href="'+esc(downloadHref(file))+'" download="'+esc(downloadFileName(file))+'"><span class="download-type">'+esc(downloadFileName(file).split('.').at(-1).toUpperCase())+'</span><span class="download-file-copy"><strong>'+esc(file.label??downloadFileName(file))+'</strong><small>'+esc(downloadFileName(file))+'</small></span><span class="download-file-size">'+downloadSize(file.bytes)+'</span><span class="download-arrow" aria-hidden="true">↓</span></a>';}
function downloadSubmission(){const file=window.DBI_DOWNLOADS.submission,a=document.createElement('a');a.href=downloadHref(file);a.download=downloadFileName(file);document.body.appendChild(a);a.click();a.remove();}
function downloads(){const C=window.DBI_DOWNLOADS;if(!C)return '<section class="card"><h2>Không tải được danh mục dữ liệu</h2><p>Vui lòng tải lại trang.</p></section>';return '<section class="download-hero"><div><div class="eyebrow">HỒ SƠ NGHIÊN CỨU · NHÓM 03</div><h2>Bộ file dùng để nộp bài.</h2><p>Báo cáo, bộ Excel bản cuối, mã nguồn và tài liệu tham chiếu.</p><div class="download-hero-stats"><span><b>4</b> file Excel</span><span><b>140</b> tiêu chí</span><span><b>6</b> trụ cột</span></div></div><div class="download-pack"><span class="download-pack-icon" aria-hidden="true">↓</span><h3>Tải bộ hồ sơ</h3><p>Gồm báo cáo, 4 Excel, code và hướng dẫn. PDF nguồn tải riêng ở cuối trang.</p><a class="button download-primary" href="'+esc(downloadHref(C.submission))+'" download>Tải bộ hồ sơ · '+downloadSize(C.submission.bytes)+' ↓</a></div></section><section class="submission-section"><div class="download-library-heading"><div><h2>Bộ Excel bản cuối</h2><p>Chọn từng file hoặc tải cả bộ 4 Excel.</p></div><a class="button" id="download-excel-pack" href="'+esc(downloadHref(C.core))+'" download>↓ Tải 4 Excel</a></div><div class="workbook-grid">'+C.files.map((f,i)=>'<section class="card workbook-card"><span class="eyebrow">EXCEL 0'+(i+1)+'</span><h3>'+esc(f.title)+'</h3><p>'+esc(f.description)+'</p>'+downloadLink({...f,label:'Tải Excel'},'download-file download-featured-link')+'</section>').join('')+'</div></section><section class="submission-section"><div class="download-library-heading"><div><h2>Báo cáo và mã nguồn</h2><p>Nội dung nghiên cứu và tài liệu để chạy lại sản phẩm.</p></div></div><div class="submission-document-grid"><section class="card"><span class="eyebrow">BÁO CÁO NGHIÊN CỨU</span><h3>Báo cáo tổng hợp</h3><p>Nội dung, quy trình, phương pháp, kết quả, phụ lục và tiêu chí chấm.</p>'+downloadLink({...C.report,label:'Tải báo cáo PDF'})+'</section><section class="card"><span class="eyebrow">MÃ NGUỒN</span><h3>Code và hướng dẫn chạy</h3><p><a class="link" href="https://github.com/soitang733/digital-banking-nhom3" target="_blank" rel="noopener noreferrer">Xem repository GitHub ↗</a></p><p>Pipeline xử lý dữ liệu, mã website và cấu hình triển khai.</p>'+downloadLink({...C.code,label:'Tải mã nguồn ZIP'})+'</section></div><div class="submission-links">'+downloadLink({...C.readme,label:'Hướng dẫn bộ file và tham chiếu thư mục'})+'<a class="button" href="https://digital-banking-nhom3.vercel.app/#overview">Mở sản phẩm ↗</a></div></section><section class="submission-section"><details class="download-group source-pdf-section"><summary><span class="download-group-number">PDF</span><span><strong>Tài liệu nguồn tham chiếu</strong><small>'+C.pdfCount+' báo cáo có trong phần dẫn chứng và đối chiếu.</small></span><span class="download-group-count">'+C.pdfCount+' PDF</span><span class="download-chevron" aria-hidden="true">⌄</span></summary><div class="source-pdf-body"><label for="download-pdf-bank">Chọn ngân hàng</label><select id="download-pdf-bank"><option value="all">Tất cả ngân hàng</option>'+D.banks.map(b=>'<option value="'+esc(b.name)+'">'+esc(b.label)+'</option>').join('')+'</select><div id="download-results"></div></div></details></section>';}
function renderDownloadResults(){const C=window.DBI_DOWNLOADS,selected=$('#download-pdf-bank').value;const files=C.pdfs.filter(f=>selected==='all'||!selected||f.bank===selected);$('#download-results').innerHTML=files.map(f=>downloadLink(f)).join('');}
function bindDownloads(){if(S.page!=='downloads'||!window.DBI_DOWNLOADS)return;$('#download-pdf-bank').onchange=renderDownloadResults;renderDownloadResults();}
